require_once '../config/database.php';require_once '../config/response.php';require_once '../eventos/helpers.php';$in=readJson();$cliente=trim($in['cliente']??'');$origem=trim($in['origem']??'');$destino=trim($in['destino']??'');$data=trim($in['data_saida']??'');$pass=max(1,(int)($in['passageiros']??1));$tipo=trim($in['tipo']??'');$obs=trim($in['observacao']??'');if($origem===''||$destino===''||$data==='')jsonResponse(false,'Origem, destino e data são obrigatórios.',[],400);$codigo='BCMR-'.date('ymd').'-'.strtoupper(substr(bin2hex(random_bytes(3)),0,6));$s=$conn->prepare("INSERT INTO viagens(empresa_id,codigo,cliente_nome,origem,destino,data_saida,passageiros,tipo,observacao,status) VALUES(3,?,?,?,?,?,?,?,?,'AGENDADA')");$s->bind_param('sssssiss',$codigo,$cliente,$origem,$destino,$data,$pass,$tipo,$obs);$s->execute();$id=(int)$conn->insert_id;$h=$conn->prepare("INSERT INTO viagens_historico(viagem_id,status_novo,observacao) VALUES(?,'AGENDADA','Solicitação pelo site público')");$h->bind_param('i',$id);$h->execute();criarEventoENotificar($conn,3,0,'Nova viagem '.$codigo,$origem.' → '.$destino,'ATENCAO','VIAGEM',$id,'NOVA_VIAGEM:'.$id,'VIAGENS','NOVA_VIAGEM');enfileirarSheets($conn,3,'VIAGEM','VIAGEM',$id);jsonResponse(true,'Viagem solicitada.',['id'=>$id,'codigo'=>$codigo]);
